using System;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using Racer;
public static class StartSevenJumpAI{public static string Main(){if(Application.isPlaying||EditorApplication.isCompiling)throw new Exception("Compiled edit mode required");EditorSceneManager.OpenScene("Assets/Scenes/DansBackyardReverse.unity");AudioListener.volume=0;foreach(var traffic in UnityEngine.Object.FindObjectsByType<ContinuationTraffic>())traffic.enabled=false;new GameObject("Temporary pool-house AI check").AddComponent<SevenJumpAI>();EditorApplication.delayCall+=()=>EditorApplication.isPlaying=true;return "Started bounded pool-house production AI check";}}
